  var clock=new com.vandorlabs.animation.VisualClock();near((float)clock.sample(0,false),0,"clock start");near((float)clock.sample(50000000,false),1,"clock step");near((float)clock.sample(100000000,true),1,"pause");near((float)clock.sample(1000000000,true),1,"paused clock correction");near((float)clock.sample(1050000000,false),1,"resume without jump");near((float)clock.sample(1100000000,false),2,"resumed progression");System.out.println("[vandorlabs][door-visual-motion] CPU PASS ordinary9/Large12ticks, repeated OPEN, reversal, position replacement, world unload,1024owner bound and pause/resume");
